mapper.select:
SELECT *
FROM (
SELECT
memNo, memId, memName, memPhone, memEmail, memState,
TO_CHAR(memDate, 'YYYY-MM-DD') AS memDate,
ROW_NUMBER() OVER (ORDER BY memNo ASC) AS rn
FROM member
WHERE memState = #{memState}
)
WHERE rn BETWEEN #{startRow} AND #{endRow}

SELECT COUNT(*) FROM member WHERE 1=1
AND (memId LIKE '%' || #{keyword} || '%' OR memName LIKE '%' || #{keyword} || '%')
AND memState = #{memState}
